	err := deployer.roll(t.Context(), delivery.Intent{Role: "ts-auth", ArtifactDigest: strings.Repeat("a", 64)},
		time.Second, io.Discard)
	if !errors.Is(err, errFencePrepare) {
		t.Fatalf("roll: %v", err)
	}
}

