func (f *channelFleet) Latest(unit string) (rolloutexec.HealthProof, bool) {
	proof, ok := f.units[unit]
	proof.ObservedAt, proof.ReceivedAt = f.now, f.now
	return proof, ok
}

func (f *channelFleet) Step(_ context.Context, step rolloutexec.Step) (rolloutexec.StepReply, error) {
	f.steps = append(f.steps, step.Unit)
	proof := f.units[step.Unit]
	proof.BinarySHA256, proof.ProcessID = step.Digest, proof.ProcessID+1
	proof.StartNonce = fmt.Sprintf("%032x", proof.ProcessID)
	f.units[step.Unit] = proof
	return rolloutexec.StepReply{OperationID: step.OperationID, Unit: step.Unit, Outcome: rolloutexec.OutcomeActivated}, nil
}

func (s *Store) IsKnownBad(ctx context.Context, digest string) (bool, error) {
	if !digestRE.MatchString(digest) {
		return false, fmt.Errorf("%w: known-bad digest", ErrInvalid)
	}
	state, _, err := s.Cell(ctx)
	if err != nil {
		return false, err
	}
	return s.knownBad(ctx, state, digest)
}

// Active returns the record that holds the cell's rollout slot and its KV
// revision. ok is false when the slot is free or names a claim whose record
// was never created; Begin repairs such a slot.
func (s *Store) Active(ctx context.Context) (record Record, revision uint64, ok bool, err error) {
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return Record{}, 0, false, err
	}
	record, revision, err = s.Load(ctx, state.ActiveRolloutID)
	if errors.Is(err, ErrAbandonedRollout) {
		return Record{}, 0, false, nil
	}
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, false, nil
	}
	if err != nil {
		return Record{}, 0, false, err
	}
	return record, revision, true, nil
}

// RecoverReservation abandons a record-free slot before program planning, including a marker-before-clear crash.
func (s *Store) RecoverReservation(ctx context.Context, epoch uint64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return err
	}
	if _, _, err := s.Load(ctx, state.ActiveRolloutID); !errors.Is(err, jetstream.ErrKeyNotFound) && !errors.Is(err, ErrAbandonedRollout) {
		return err
	}
	if err := s.abandon(ctx, epoch, state.ActiveRolloutID); err != nil {
		return err
	}
	return s.releaseSlot(ctx, epoch, state.ActiveRolloutID)
}

func (s *Store) abandon(ctx context.Context, epoch uint64, rolloutID string) error {
	encoded, err := protocol.EncodeJSON(abandonedMarker{AbandonedRollout: rolloutID})
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = s.kv.Create(ctx, rolloutKey(rolloutID), encoded)
	if errors.Is(err, jetstream.ErrKeyExists) {
		// A concurrent create won or the marker is already in place; the
		// next Load tells which.
		if _, _, loadErr := s.Load(ctx, rolloutID); loadErr == nil {
			return ErrActiveRollout
		} else if !errors.Is(loadErr, ErrAbandonedRollout) {
			return loadErr
		}
		return nil
	}
	return err
}

// releaseSlot refunds a proven release reservation once, in the CAS that clears it.
func (s *Store) releaseSlot(ctx context.Context, epoch uint64, rolloutID string) error {
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return err
		}
		if state.ActiveRolloutID != rolloutID {
			return nil
		}
		if _, _, err := s.Load(ctx, rolloutID); !errors.Is(err, ErrAbandonedRollout) {
			if err != nil {
				return err
			}
			return ErrActiveRollout
		}
		release, _, found, err := s.releaseStage(ctx, rolloutID)
		if err != nil {
			return err
		}
		next := state
		next.ActiveRolloutID = ""
		next.Attempts = maps.Clone(state.Attempts)
		// An arbitrary orphan ID proves no target; never guess from historical counts.
		if found && next.Attempts[release.Digest] > 0 {
			if next.Attempts[release.Digest]--; next.Attempts[release.Digest] == 0 {
				delete(next.Attempts, release.Digest)
			}
		}
		if err := s.writeCell(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else {
			return err
		}
	}
	return ErrConflict
}

func (e *Executor) Tick(ctx context.Context) error {
	snapshot := e.Fencer.Current()
	if !snapshot.CanMutate() {
		e.forget("")
		return nil
	}
	if e.issued == nil {
		e.forget("")
	}
	if err := e.Store.RecoverReservation(ctx, snapshot.Epoch); err != nil {
		return err
	}
	record, revision, ok, err := e.Store.Active(ctx)
	if err != nil {
		return err
	}
	if !ok {
		e.forget("")
		if err := e.startNext(ctx, snapshot.Epoch); err != nil {
			e.waiting = err.Error()
			e.publish(snapshot.Epoch, nil)
			return err
		}
		if record, revision, ok, err = e.Store.Active(ctx); err != nil || !ok {
			e.publish(snapshot.Epoch, nil)
			return err
		}
	}
	if record.RolloutID != e.rolloutID {
		e.forget(record.RolloutID)
	}
	if record.AuthorityEpoch != snapshot.Epoch && !record.Phase.Terminal() {
		id := record.RolloutID
		if record, revision, err = e.Store.Adopt(ctx, id, snapshot.Epoch); err != nil {
			return fmt.Errorf("adopt rollout %s: %w", id, err)
		}
	}
	if record.Phase.Terminal() {
		e.forget(record.RolloutID)
		e.publish(snapshot.Epoch, &record)
		return e.Store.Settle(ctx, record, snapshot.Epoch)
	}
	defer func() { e.publish(snapshot.Epoch, &record) }()
	for range maxRounds {
		before := revision
		if record.Phase == rollout.PhasePending {
			if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventStart, At: e.now()}); err != nil {
				return err
			}
		}
		// Deadlines are committed before any effect is derived: a tick
		// that resumes after a deadline rolls back (or freezes) instead of
		// still sending the expired step.
		if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventTick, At: e.now()}); err != nil {
			return err
		}
		if record.Phase.Terminal() {
			break
		}
		events, err := e.act(ctx, record)
		if err != nil {
			return err
		}
		for _, event := range events {
			if err := e.apply(ctx, &record, &revision, event); err != nil {
				return err
			}
		}
		if err := e.apply(ctx, &record, &revision, rollout.Event{Kind: rollout.EventTick, At: e.now()}); err != nil {
			return err
		}
		if revision == before || record.Phase.Terminal() {
			break
		}
	}
	return nil
}

func (e *Executor) startNext(ctx context.Context, epoch uint64) error {
	e.waiting = ""
	if e.Program == nil {
		return nil
	}
	program, err := e.Program(ctx)
	if err != nil {
		return fmt.Errorf("read rollout program: %w", err)
	}
	for _, spec := range program {
		existing, _, err := e.Store.Load(ctx, spec.RolloutID)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			now := e.now()
			if spec.StartedAt.After(now) {
				e.waiting = fmt.Sprintf("the release is issued at %s; waiting for the cell clock", spec.StartedAt)
				return nil
			}
			spec.AuthorityEpoch = epoch
			if _, _, err := e.Store.Begin(ctx, spec, now); err != nil {
				return fmt.Errorf("begin rollout %s: %w", spec.RolloutID, err)
			}
			return nil
		}
		if err != nil {
			return e.halt(spec.RolloutID, err.Error())
		}
		// A completed record only satisfies the program step it was
		// planned from: the same ID with another target, kind, waves or
		// policy stops the program instead of skipping ahead.
		if err := existing.Matches(spec); err != nil {
			return e.halt(spec.RolloutID, err.Error())
		}
		if existing.Phase != rollout.PhaseComplete {
			return e.halt(spec.RolloutID, "rollout ended "+string(existing.Phase))
		}
	}
	return nil
}

func (p ReleaseProgram) Program(ctx context.Context) (Program, error) {
	desired, _, err := p.Store.Desired(ctx)
	if err != nil {
		return nil, err
	}
	release := desired.Release
	if release.Generation == 0 || desired.Paused || len(p.Controllers) == 0 {
		return nil, nil
	}
	id := rollout.ReleaseRolloutID(release.Generation)
	var program Program
	controllers, done, err := p.rollout(ctx, entityid.Derive(rollout.ControllerReleaseDomain, id), rollout.KindController, p.Controllers, desired)
	if err != nil {
		return nil, err
	}
	if controllers != nil {
		program = append(program, *controllers)
	}
	if controllers != nil && !done || p.Hosts == nil {
		return program, nil
	}
	units, err := p.Hosts(ctx)
	if err != nil || len(units) == 0 {
		return program, err
	}
	hosts, _, err := p.rollout(ctx, entityid.Derive(rollout.HostReleaseDomain, id), rollout.KindHost, units, desired)
	if err != nil {
		return nil, err
	}
	if hosts != nil {
		program = append(program, *hosts)
	}
	return program, nil
}

// rollout returns the generation's rollout of units: the stored one once it
// began (done when it completed), else one for the units that do not run
// the release yet, nil when there are none.
func (p ReleaseProgram) rollout(ctx context.Context, id string, kind rollout.Kind, units []rollout.Unit,
	desired rollout.Desired,
) (*rollout.Spec, bool, error) {
	existing, _, err := p.Store.Load(ctx, id)
	if err == nil {
		// The stored plan is this generation's step, whatever it ended as.
		spec := existingSpec(existing)
		return &spec, existing.Phase == rollout.PhaseComplete, nil
	}
	if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil, false, err
	}
	behind, from, err := p.Behind(units, desired.Release.Digest)
	if err != nil || len(behind) == 0 {
		return nil, false, err
	}
	if bad, err := p.Store.IsKnownBad(ctx, desired.Release.Digest); err != nil || bad {
		return nil, false, err
	}
	return &rollout.Spec{RolloutID: id, Kind: kind, Cell: desired.Cell, FromDigest: from,
		ToDigest: desired.Release.Digest, Units: behind, Policy: p.Policy,
		StartedAt: desired.Release.CreatedAt}, false, nil
}

